#!/usr/bin/env bash
# The dep-bump-fixer dedups its own PR comments via fixer_comment_count
# (scripts/github-api.sh): it matches comment bodies against FIXER_SIGNATURE
# with jq `test()` (a regex, case-sensitive). The key MUST match every footer
# skill_attribution("dep-bump-fixer") can emit — resolved (pinned-SHA markdown
# link) and linkless — plus the legacy "Generated by RepoMan dep-bump-fixer@<sha>"
# form so old comments still dedup; and it MUST be anchored to the footer so an
# unrelated comment that merely mentions the tool name does NOT count as
# already-commented (which would silently suppress analysis). automation#131
# changed the footer format; caught on #136.
#
# This test drives the REAL helper (not a standalone jq re-implementation): the
# earlier version re-coded the match and so missed that `gh pr view --jq --arg`
# is malformed (gh's --jq takes one expression, no --arg), which made the
# dedup count always 0.
set -uo pipefail
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
# shellcheck disable=SC1091
source "$SCRIPT_DIR/../scripts/program-lib.sh"
TMP=$(mktemp -d); trap 'rm -rf "$TMP"' EXIT
fail=0

# The exact signature the fixer uses for dedup (scripts/dep-bump-fixer.sh).
FIXER_SIGNATURE=$(grep -E '^FIXER_SIGNATURE=' "$SCRIPT_DIR/../scripts/dep-bump-fixer.sh" | head -1 | sed -E 's/^FIXER_SIGNATURE="(.*)"$/\1/')
[ -n "$FIXER_SIGNATURE" ] || { echo "FAIL: could not read FIXER_SIGNATURE from dep-bump-fixer.sh"; exit 1; }

# Stub the GitHub call the helper makes. fixer_comment_count calls
# `gh_with_backoff pr view <pr> --repo <repo> --json comments`; we return a
# comments payload seeded from $STUB_COMMENTS (a JSON array of body strings).
gh_with_backoff() {
  # Emit the same shape `gh --json comments` would: {"comments":[{"body":...}]}
  jq -n --argjson bodies "$STUB_COMMENTS" '{comments: [$bodies[] | {body: .}]}'
}

# Build a {comments:[...]} fixture from the given body strings and assert the
# helper's count.
expect_count() { # <want_count> <label> <body…>
  local want="$1" label="$2"; shift 2
  STUB_COMMENTS=$(printf '%s\n' "$@" | jq -R . | jq -s .)
  export STUB_COMMENTS
  local got; got=$(fixer_comment_count "acme/widgets" "7" "$FIXER_SIGNATURE")
  if [ "$got" = "$want" ]; then echo "PASS: $label"; else echo "FAIL: $label (want $want, got $got)"; fail=1; fi
}

# A footer-bearing comment counts; the real emitted footers must match.
meta_dir="$TMP/meta"; mkdir -p "$meta_dir"
FAKE_SHA="abcdef1234567890abcdef1234567890abcdef12"
printf '{"version":"%s","source":"rossoctl/repoman","installed_at":"2026-11-09"}\n' "$FAKE_SHA" \
  > "$meta_dir/_meta.dep-bump-fixer.json"
resolved=$(SCRIPT_DIR="$meta_dir" SKILL_SOURCE_REPO="rossoctl/repoman" skill_attribution "dep-bump-fixer")
expect_count 1 "resolved footer is counted" "$resolved"

empty_dir="$TMP/empty"; mkdir -p "$empty_dir"
gh() { return 1; }
unresolved=$(SCRIPT_DIR="$empty_dir" SKILL_SOURCE_REPO="rossoctl/repoman" skill_attribution "dep-bump-fixer" 2>/dev/null)
unset -f gh
expect_count 1 "linkless footer is counted" "$unresolved"

expect_count 1 "legacy RepoMan footer is counted" \
  "Generated by RepoMan dep-bump-fixer@235a7f7 (https://github.com/x)."

# Bare mentions must NOT be counted (anchored key).
expect_count 0 "bare tool mention is not counted" \
  "dep-bump-fixer skipped this one, looks fine"
expect_count 0 "a link to the skill dir is not counted" \
  "see https://github.com/rossoctl/repoman/tree/main/skills/dep-bump-fixer/"

# Mixed: one real footer among noise -> counts exactly the footer.
expect_count 1 "footer counted among unrelated comments" \
  "dep-bump-fixer looks great" "$resolved" "lgtm"

[ "$fail" -eq 0 ] && echo "PASS: dep-bump-fixer dedup counts footers, rejects mentions" || exit 1
